BEGIN READ ONLY;
WITH p AS (SELECT id,coalesce(raw_data->>'building_id',raw_data->'building'->>'id') bid,raw_data FROM public.properties WHERE source='novos' AND external_id LIKE 'orulo:%'),
f AS (SELECT id,bid,x.plan,x.plan->>'id' pid FROM p CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(raw_data->'building'->'floor_plans')='array' THEN raw_data->'building'->'floor_plans' ELSE '[]'::jsonb END)x(plan)),
u AS (SELECT id,bid,pid,e.key,CASE WHEN jsonb_typeof(e.value)='string' THEN e.value#>>'{}' ELSE e.value::text END url FROM f CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(plan)='object' THEN plan ELSE '{}'::jsonb END)e WHERE e.key IN ('image_url','url','520x280','1024x1024','2280x1800') AND e.value<>'null'::jsonb AND e.value<>'""'::jsonb
UNION ALL SELECT id,bid,pid,'images',CASE WHEN jsonb_typeof(v)='string' THEN v#>>'{}' ELSE v::text END FROM f CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(plan->'images')='array' THEN plan->'images' ELSE '[]'::jsonb END)a(v)),
cross_plan AS (SELECT url,count(DISTINCT (bid,pid)) n FROM u GROUP BY url HAVING count(DISTINCT (bid,pid))>1),
arrays AS (SELECT id,bid,pid,count(*)-count(DISTINCT v) n FROM f CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(plan->'images')='array' THEN plan->'images' ELSE '[]'::jsonb END)a(v) GROUP BY id,bid,pid HAVING count(*)>count(DISTINCT v))
SELECT (SELECT count(*) FROM u) image_field_references,(SELECT count(DISTINCT url) FROM u) distinct_urls,(SELECT count(*) FROM cross_plan) urls_shared_across_distinct_plans,(SELECT coalesce(sum(n-1),0) FROM cross_plan) excess_distinct_plan_url_associations,(SELECT count(*) FROM arrays) plan_occurrences_with_duplicate_image_array_entries,(SELECT coalesce(sum(n),0) FROM arrays) duplicate_array_entries,(SELECT count(*) FROM u WHERE url !~ '^https://static[.]orulo[.]com[.]br/images/properties/[A-Za-z0-9_-]+/[A-Za-z0-9_-]+[.]([jJ][pP][eE]?[gG]|[pP][nN][gG]|[wW][eE][bB][pP])$') invalid_url_references,(SELECT count(DISTINCT (id,pid)) FROM u WHERE url !~ '^https://static[.]orulo[.]com[.]br/images/properties/[A-Za-z0-9_-]+/[A-Za-z0-9_-]+[.]([jJ][pP][eE]?[gG]|[pP][nN][gG]|[wW][eE][bB][pP])$') plan_occurrences_with_invalid_urls;
COMMIT;
